  "codebook": {
    "clarification": "Include: (1) announcements by the senator that a state or local entity received federal funds, grants, projects, designations, facilities, or military missions — the senator's act of announcing functions as a claim of responsibility even without the verb 'secured'; (2) explicit claims such as 'I helped secure,' 'my request,' 'funding I requested,' 'legislation I authored'; (3) shared credit with state delegation members or named colleagues; (4) claims that the senator's letter, appeal, nomination, pressure, or oversight preceded and helped produce an agency action (e.g., a waiver, purchase, disaster declaration, loan eligibility, or appointment); (5) claims of authorship of legislation that has advanced beyond introduction (passed a committee or chamber, or been signed into law), or that the senator's amendment/provision was included in such advancing legislation; (6) claimed results from oversight activity (e.g., taxpayer funds recouped).",
    "definition": "A senator is credit-claiming when the press release asserts, explicitly or implicitly, that the senator (alone, with the state delegation, or with named colleagues) is personally responsible for bringing about a government action or benefit valued by constituents — for example, federal grants, appropriations, earmarks, projects, designations, facilities, military missions, disaster declarations, appointments, legislation the senator authored that advanced or became law, amendments or provisions the senator inserted into advancing legislation, or agency decisions produced by the senator's request, pressure, or oversight.",
    "negative_clarification": "Do NOT classify as credit-claiming: (1) position-taking on issues, explanations of votes, or criticism of the administration/opponents; (2) introducing or cosponsoring legislation, or advocating future action, without claiming an achieved outcome; (3) welcoming or applauding a government decision without claiming a causal role in it; (4) ceremonial content — awards presented to constituents, commemorations, condolences, tributes, town meeting or event announcements; (5) oversight or hearing statements whose primary purpose is criticism or advocacy, even when past legislative work is mentioned incidentally; (6) touting one's voting record or accepting third-party awards; (7) general economic or policy cheerleading without a specific governmental action attributed to the senator.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Kennedy introduces stem cell legislation and argues for its future benefits. Because the bill is only being introduced and no benefit has been delivered or enacted, the release is position-taking/advocacy rather than credit-claiming."
      },
      {
        "document_id": "656",
        "explanation": "Kerry's statement on the Dubai ports deal is entirely criticism of the Bush administration's port security failures; he claims no personal accomplishment or delivered benefit."
      },
      {
        "document_id": "3577",
        "explanation": "Sarbanes' hearing statement criticizes FEMA and calls for reforms. Although he mentions he worked on past reforms, the release's purpose is oversight criticism and advocacy, not claiming a delivered benefit, so it is not credit-claiming."
      }
    ],
    "positive_examples": [
      {
        "document_id": "2627",
        "explanation": "Talent announces the Senate 'approved his request' for $1.5 million for a University of Missouri research center — an explicit, first-person claim of responsibility for securing a federal appropriation for his state."
      },
      {
        "document_id": "2318",
        "explanation": "Durbin explicitly states 'I helped secure an expedited environmental review' and 'facilitated the return of the project to the national priority list' for a local airport project — direct claims of personal responsibility for government actions benefiting constituents."
      },
      {
        "document_id": "873",
        "explanation": "Landrieu frames Medicare's decision to waive late-enrollment penalties for hurricane-affected seniors as the result of her letter and the delegation's pressure ('the agency has finally come to its senses'), an implicit claim that her intervention produced the government action."
      }
    ]
  }
}
